// Canonicals and publisher are derived to keep every article on the main domain.
export function publishedArticles(now = Date.now()) {
  return articles.filter(a => a.published && Date.parse(a.datePublished) <= now)
    .map(a => ({...a, canonicalURL: `${BLOG_ORIGIN}/blog/${a.slug}`, publisher: PUBLISHER}))
    .sort((a,b) => b.datePublished.localeCompare(a.datePublished) || a.slug.localeCompare(b.slug));
}
